"""AnimeShooter official audio-annotation sample: six benchmark shots for H3."""
from pathlib import Path
import os, zipfile, json
root=Path(__file__).resolve().parents[1]
z=zipfile.ZipFile(Path(os.environ["TEMP"])/"animeshooter_audio_20261031.zip")
source_path="audio_scripts_changed_keys/7ozRwX35fHE.json"
data=json.loads(z.read(source_path))
segment_index=1
segment=data["segments"][segment_index]
story=segment["story script"]
shots=[["S01","2D hand-painted storybook animation with delicate ink outlines and subdued watercolor textures. Overcast meadow beside a scattering of grey rocks and a distant lake. In a medium-wide composition, a fair-skinned girl with short light-brown bob hair and a tiny side ponytail, white ruffled short-sleeved blouse, red skirt and white stockings walks from frame left toward a dark green bush. A second fair-skinned girl with long blonde hair, small red flower hairpins and a long white dress peeks from behind the leaves at frame right. During the first two seconds the brunette approaches; during the next two she opens her palm to reveal one small brown seed; in the final second the blonde carefully takes it and smiles. Slow push-in of small amplitude, gentle natural arm gestures, fixed costume and one seed only.","Grass swishes gently in the wind, soft footsteps, a little rustle as the girl emerges from behind the bush.","Gentle celesta notes over light sustained strings."],["S02","2D storybook anime with muted watercolor palette, ink outlines and natural hand-drawn motion. In a wide lateral tracking shot across the same cloudy meadow of muted grasses, rocks and a distant lake, two girls run side-by-side from left to right. The left girl has a light-brown bob with tiny side ponytail, white ruffled blouse and red skirt; the right girl has long blonde hair with red flower clips and a flowing long white dress. From 0 to 2 seconds they break into an excited run, from 2 to 4 seconds their hair and skirts respond to the running rhythm, and by 5 seconds they move toward a distant old-fashioned two-story house. A smooth tracking camera follows their movement at walking-height, stable scale and recognizable silhouettes.","Light footsteps in grass, soft rustling fabric and the girls' wordless delighted breaths, breezy outdoor ambience.","Bouncy but restrained plucked strings with light flute accents."],["S03","2D hand-painted storybook animation, cool overcast afternoon. Establishing medium-long shot of a dark old-fashioned two-story country house with a distinctive chimney and wooden porch steps. A pale middle-aged man with short dark hair, a neat dark mustache, a charcoal suit and black bow tie stands at the top of the porch stairs. He keeps his hands near the rails. From 0 to 2 seconds he looks down the path; from 2 to 4 seconds he draws a quiet sigh and lowers his shoulders; during the final second he lifts his eyes toward someone arriving outside the frame. Static camera with subtle parallax of nearby leaves, no other people in frame.","Wooden porch boards creak faintly, distant birds and a restrained human sigh.","One sustained low cello tone under sparse piano."],["S04","2D dramatic storybook anime with delicate linework and muted watercolors. Close-up on the fair-skinned brunette girl with short light-brown bob hair and tiny side ponytail, wearing the same white ruffled blouse and red skirt, against a darkening meadow and rocks. At 0 to 2 seconds her eyes widen at something off-screen and her breath catches; at 2 to 3 seconds a distant storm cloud passes across the light; from 3 to 5 seconds the camera pulls back slowly with small amplitude to show the girl standing by a leafless tree, shoulders drooping and looking at a small brown seed lying on the grass near her shoes. Natural restrained emotion, no abrupt identity or costume changes.","A brief low rumble of distant thunder followed by wind through grass and a quiet shaky breath.","Soft descending piano notes and an understated string drone."],["S05","2D hand-painted storybook animation, subdued ink outlines and cool grey skies. At the wooden porch of the same dark two-story old-fashioned house with a chimney, a pale man with short dark hair, neat mustache, charcoal suit and bow tie stands beside an open entrance. A fair-skinned young girl with a light-brown bob, tiny side ponytail, white ruffled blouse, red skirt, and white stockings approaches with her head lowered. From 0 to 2 seconds the man silently gestures with an open palm toward the doorway; from 2 to 4 seconds the girl passes him slowly, looking down; in the final second he turns his shoulders to follow. Medium-wide static framing at eye level, clear natural walking and consistent spatial positions.","Footsteps on aged wooden steps, soft fabric movement, a quiet porch creak and distant wind.","Sparse low piano notes at a slow tempo."],["S06","2D illustrated storybook animation, quiet melancholic exterior establishing shot of the same looming two-story old-fashioned country house, dark roof, chimney and wooden porch amid a sparsely vegetated meadow. A heavy grey storm sky dominates the upper half of the picture. Over 0 to 2 seconds a single red flower petal drifts down through foreground air; over 2 to 4 seconds it twists gently and descends toward the porch path while the camera holds a wide static composition; in the final second the scene gradually fades toward black. No characters and no text overlays. Soft watercolor texture, consistent setting geometry.","Faint wind moving dry grass, a distant low thunder rumble; otherwise quiet countryside air.","A solitary piano note fades under an almost silent string harmonic."]]
assert data["video ID"]=="7ozRwX35fHE" and len(story["shots"])>=6 and len(shots)==6
previous=json.loads((root/"tasks"/"016_t2f_004_h3_skill_5s.json").read_text(encoding="utf-8"))
jobs=[]
for i,(name,visual,sound,music) in enumerate(shots):
    prompt="integrated_multimodal_description: [Shot 1] "+visual+"\n\noverall_soundscape: "+sound+"\n\nnon_diegetic_music: "+music
    jobs.append({"name":name,"set":{"140:131.prompt":prompt,"140:133.value":5,"92.filename_prefix":"video/017_animeshooter_seed_h3_"+name}})
task={"name":"017_animeshooter_seed_h3_5s","steps":[{"id":"video","workflow":previous["steps"][0]["workflow"],"endpoint":previous["steps"][0]["endpoint"],"foreach":jobs}]}
target=root/"tasks"/"017_animeshooter_seed_h3_5s.json"
assert not target.exists(),"Do not overwrite existing task"
target.write_text(json.dumps(task,ensure_ascii=False,indent=2),encoding="utf-8")
metadata={"dataset":"qiulu66/AnimeShooter","dataset_subset":"AnimeShooter-audio","source_json":source_path,"video_id":data["video ID"],"segment_index":segment_index,"source_url":data["url"],"license":"CC BY-NC 4.0 / academic only","storyline":story["storyline"],"characters":story["main characters"],"scenes":story["main scenes"],"shot_alignment":[{"generated":f"S{i+1:02}","source_shot":i,"source_narrative":story["shots"][i]["visual annotation"]["narrative caption"],"original_start":story["shots"][i]["start time"],"original_end":story["shots"][i]["end time"]} for i in range(6)],"adaptation":"time normalized to 5 seconds per shot; original assets not downloaded; text-only T2V; no identity reference images","excluded_source_shot":6}
(root/"tasks"/"017_animeshooter_seed_h3_provenance.json").write_text(json.dumps(metadata,ensure_ascii=False,indent=2),encoding="utf-8")
print("READY shots",len(jobs),"source",source_path,"segment",segment_index,"all three prompt sections",all(p in jobs[0]["set"]["140:131.prompt"] for p in ["integrated_multimodal_description:","overall_soundscape:","non_diegetic_music:"]))
